  "~{d} min  ·  {n} exercícios": ["~{d} min  ·  {n} exercises", "~{d} min  ·  {n} ejercicios", "~{d} min  ·  {n} exercises", "~{d} min  ·  {n} exercises", "~{d} min  ·  {n} exercices"],
